program='''from collections import deque

def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        stack.append((nx, ny))
            result.append(cells)
    return result

def signature(cells):
    top = min(r for r, c in cells)
    left = min(c for r, c in cells)
    return frozenset((r - top, c - left) for r, c in cells)

def transform(grid):
    out = [row[:] for row in grid]
    examples = {}
    for color in range(2, 10):
        for cells in components(grid, color):
            examples.setdefault(signature(cells), color)
    for cells in components(grid, 1):
        color = examples.get(signature(cells))
        if color is not None:
            for r, c in cells:
                out[r][c] = color
    return out
'''
